INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT159-S3-Q2$batch05$, 159, 3, 2, $batch05$Necessary Assumption$batch05$, $batch05$Entertainment reporter: Unlike most major motion pictures, the release of the upcoming film Escapade II has not been preceded by free, advance screenings that show the film to select audiences for promotional purposes. With movie research showing awareness of the film at 96 percent, and with around 60 percent of filmgoers indicating “definite interest” in the film, the film’s distributors must have decided not to do anything that could reduce interest in the film.$batch05$, $batch05$The entertainment reporter’s explanation for why there have been no advance screenings of Escapade II relies on assuming that the distributors believe that$batch05$, $batch05$B$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$advance screenings of Escapade II would cost them a significant amount that could much more effectively be spent on advertising$batch05$, $batch05$Weakens$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$advance screenings of Escapade II might lead to a dampening of the enthusiasm of filmgoers who would otherwise have an interest in seeing the film$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$the select audiences who would normally be invited to free, advance screenings of a major motion picture would probably not enjoy Escapade II$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$if 96 percent of the public is aware of the upcoming release of Escapade II, it is probable that 96 percent of the public intends to see the film$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$the film Escapade II would most likely be viewed by approximately 60 percent of the public if no advance screenings are given$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The distributors skipped advance screenings because they decided not to do anything that could reduce interest in the film.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Awareness of the film is at 96 percent, and about 60 percent of filmgoers say they are definitely interested.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The reporter explains skipping screenings as a way to protect interest. That only makes sense if the distributors thought screenings *could* hurt interest. If they thought screenings could only help, avoiding them would not protect anything. The question even tells you the answer is about what the distributors *believe*.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: the distributors believed screenings might reduce interest in the film.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Cost is a different reason to skip the screenings. That competes with the reporter's explanation instead of supporting it.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "the distributors believed screenings would *not* dampen anyone's enthusiasm." Then skipping them does nothing to protect interest, and the reporter's explanation stops making sense.$batch05$), ($batch05$C$batch05$, $batch05$The distributors only need to think screenings *might* hurt interest. They do not need to predict that the audiences would dislike the film.$batch05$), ($batch05$D$batch05$, $batch05$Whether awareness turns into ticket sales is not part of the explanation.$batch05$), ($batch05$E$batch05$, $batch05$A specific prediction about how many people see the film goes beyond what the explanation needs.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT159-S3-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
